'use client';
import { useMemo } from 'react';
import { useSetAtom } from '../../react.js';
import { atom } from '../../vanilla.js';
export function useAtomCallback(callback, options) {
    const anAtom = useMemo(() => atom(null, (get, set, ...args) => callback(get, set, ...args)), [callback]);
    return useSetAtom(anAtom, options);
}
